return $input.all().map(item => {
  const styles = `
<style>
  @page {
    size: A4;
    margin: 16mm;
  }

  body {
    font-family: Arial, sans-serif;
    font-size: 10pt;
    line-height: 1.45;
    color: #253247;
  }

  h1 {
    font-size: 20pt;
    line-height: 1.2;
    color: #17365d;
    margin: 0 0 16px;
  }

  h2, h3 {
    color: #17365d;
    margin: 18px 0 8px;
    break-after: avoid;
  }

  p, ul, ol {
    margin: 8px 0;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
    margin: 12px 0 18px;
  }

  th, td {
    padding: 8px 10px;
    border-bottom: 1px solid #dce3ec;
    vertical-align: top;
  }

  th {
    background: #edf2f8;
    text-align: left;
  }

  thead {
    display: table-header-group;
  }

  tr {
    break-inside: avoid;
  }

  h2:has(+ p img) {
    break-before: page;
  }

  h2 + p:has(img) {
    break-inside: avoid;
  }

  img {
    display: block;
    max-width: 100%;
    max-height: 75mm;
    width: auto;
    height: auto;
    margin: 12px auto;
    break-inside: avoid;
  }

  a {
    color: #175ca4;
    overflow-wrap: anywhere;
  }

  li {
    margin-bottom: 5px;
  }
</style>`;

  let html = item.json.html;

  if (typeof html !== 'string' || !html.trim()) {
    throw new Error('Expected report HTML in the html field.');
  }

  const analysis = JSON.parse($('When Executed by Another Workflow').first().json.analysis_result);
  const missing = (analysis.coverage ?? []).filter(row => row.status !== 'supported');
  const escape = value => String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  if (missing.length) {
    const banner = `<section style="border:2px solid #b45309;background:#fff7ed;padding:12px;margin:12px 0"><strong>Incomplete research report</strong><p>The following required answers are not established by the verified evidence:</p><ul>${missing.map(r=>`<li>${escape(r.description)}</li>`).join('')}</ul></section>`;
    html = html.replace(/<body[^>]*>/i, match => match + banner);
  }


  const styledHtml = /<\/head>/i.test(html)
    ? html.replace(/<\/head>/i, `${styles}</head>`)
    : `<!DOCTYPE html>
<html>
<head><meta charset="utf-8">${styles}</head>
<body>${html}</body>
</html>`;

  return {
    ...item,
    json: {
      ...item.json,
      html: styledHtml
    }
  };
});

const htmlFile = $('Convert to File').first().binary?.data;
const chartFile = $input.first().binary?.chart;
const filename = $('Prepare Report for PDF').first().json.chart_file;

if (!htmlFile) {
  throw new Error('The index.html attachment is missing.');
}

if (!chartFile) {
  throw new Error(`Saved chart could not be read: ${filename}`);
}

return [{
  json: {},
  binary: {
    data: {
      ...htmlFile,
      fileName: 'index.html',
      mimeType: 'text/html'
    },
    chart: {
      ...chartFile,
      fileName: filename,
      mimeType: 'image/png',
      fileExtension: 'png'
    }
  }
}];

const html = $input.first().json.html;
const chartFile =
  $('When Executed by Another Workflow').first().json.chart_url;

if (typeof html !== 'string' || !html.trim()) {
  throw new Error('Report HTML is missing.');
}

if (
  typeof chartFile !== 'string' ||
  (chartFile !== '' && !/^chart-\d+\.png$/.test(chartFile))
) {
  throw new Error('Invalid saved chart filename.');
}

return [{
  json: {
    output: html,
    chart_file: chartFile
  }
}];

const report = $('Prepare Report for PDF').first().json;
const candidate = $('Select licensed source image').first().json;
let html = report.output;
if (candidate.image_url && /src="data:image\/(?:png|jpeg|webp);base64,/i.test(html)) {
  const safeUrl = candidate.image_url.replace(/&/g,'&amp;').replace(/"/g,'&quot;');
  html = html.replace(/src="data:image\/(?:png|jpeg|webp);base64,[^"]+"/i, `src="${safeUrl}"`);
}
return [{json:{report_html:html,pdf_file:'report-'+$execution.id+'.pdf'}}];

const item = $input.first();
let evidence = {accepted_passages: [], image_candidates: []};
try {
  const parsed = JSON.parse($('When Executed by Another Workflow').first().json.research_evidence);
  if (parsed && Array.isArray(parsed.accepted_passages) && Array.isArray(parsed.image_candidates)) evidence = parsed;
} catch (error) {
  // The chart/report path remains usable, but no unverified source image is selected.
}
const accepted = new Set(evidence.accepted_passages.map(p => p.url));
const candidates = evidence.image_candidates.filter(c => accepted.has(c.source_url));
function publicHttps(value) {
  try {
    const u = new URL(value);
    const h = u.hostname.toLowerCase();
    return u.protocol === 'https:' && !/^(localhost|.*\.local|.*\.internal)$/.test(h) &&
      !/^(?:\d{1,3}\.){3}\d{1,3}$/.test(h) && !h.includes(':') && !u.username && !u.password;
  } catch { return false; }
}
const c = candidates.find(c => publicHttps(c.image_url) && publicHttps(c.source_url) &&
  typeof c.caption === 'string' && c.caption.trim() &&
  typeof c.license_quote === 'string' && /(public domain|creative commons|cc\s?by|cc0|may be reused|free to use|reuse permitted)/i.test(c.license_quote) &&
  !/all rights reserved|permission required/i.test(c.license_quote));
if (!c) {
  const note = '<p><em>No suitable source image with verified reuse rights was available for this report.</em></p>';
  item.json.html = item.json.html.replace(/<\/body>/i, note+'</body>');
}
return [{json:{...item.json,image_url:c?.image_url??'',source_url:c?.source_url??'',caption:c?.caption??'',license_quote:c?.license_quote??''}}];

const original = $('Select licensed source image').first().json;
let html = original.html;
const downloaded = $input.first();
const escape = value => String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
let valid = false;
if (downloaded.binary?.sourceImage) {
  const file = downloaded.binary.sourceImage;
  const mime = String(file.mimeType ?? '').toLowerCase();
  if (['image/png','image/jpeg','image/webp'].includes(mime)) {
    const buffer = await this.helpers.getBinaryDataBuffer(0,'sourceImage');
    if (buffer.length > 0 && buffer.length <= 2*1024*1024) {
      const figure = `<figure data-source-image-url="${escape(original.image_url)}"><img src="data:${mime};base64,${buffer.toString('base64')}" alt="${escape(original.caption)}"><figcaption>${escape(original.caption)} — <a href="${escape(original.source_url)}">Source and reuse information</a></figcaption></figure>`;
      html = html.replace(/<\/body>/i, figure+'</body>');
      valid = true;
    }
  }
}
if (!valid) html = html.replace(/<\/body>/i,'<p><em>No suitable source image could be validated and downloaded for this report.</em></p></body>');
return [{json:{...original,html,image_embedded:valid}}];
